== Class Keywords ==

{| class="wikitable valign-top"
! Keyword
! Description
|-
!
=== class ===
| Declares a class
<enforce>
class ExampleClass
{
}
</enforce>
|-
!
=== modded ===
| See {{Link|Arma Reforger:Object Oriented Programming Advanced Usage#Modding}}.
<enforce>
class ExampleClass
{
}

modded class ExampleClass // inherits and "takes the place" of the original ExampleClass
{
}
</enforce>
|-
!
=== sealed ===
| A class marked with the '''sealed''' keyword cannot be inherited from
<enforce>
sealed class Infertile
{
}

class Child : Infertile // compilation error - a class cannot inherit from a sealed class
{
}
</enforce>
|-
!
=== extends ===
| states that the declared class inherits from another
<enforce>
class ChildClass extends ParentClass
{
}

// alias
class ChildClass : ParentClass
{
}
</enforce>
|-
!
=== typedef ===
| Declares an alias for a type
<enforce>
typedef string Text;

class ExampleClass
{
	Text m_sMyText = "This is my text, that is a string";
}
</enforce>
|}


== Method Keywords ==

{| class="wikitable valign-top"
! Keyword
! Description
|-
!
=== proto ===
| Disclose an engine-side method to script (Engine side).
|-
!
=== external ===
| Compiler hint to link API methods - only applies to {{hl|proto}} methods (Engine side).
|-
!
=== native ===
| Native call convention of internal method (Engine side).
|-
!
=== volatile ===
| Internal method that may call back to script (hint for compiler that context need to be saved on stack).
|-
!
=== private ===
| Modifier for class method. The method can be called only from inside of the same class' methods. A {{Link|#modded}} class will still be able to use it (but not its children).
<enforce>
class ExampleClass
{
	private void HelloWorld()
	{
		Print("Hello there");
	}

	void PublicHelloWorld()
	{
		HelloWorld(); // works from within the object
	}
}

ExampleClass classInstance = new ExampleClass();
classInstance.PublicHelloWorld();	// works - calls PublicHelloWorld() that calls HelloWorld()
classInstance.HelloWorld();			// compilation error - HelloWorld() is private and cannot be accessed
</enforce>
|-
!
=== protected ===
| Modifier for class method. The method can be called only from inside of class' methods or methods of its extended (children) classes, or a modded class.
<enforce>
class ParentClass
{
	protected void HelloWorld()
	{
		Print("Hello there");
	}
}

class ChildClass : ParentClass
{
	void PublicHelloWorld()
	{
		HelloWorld(); // works from within the object
	}
}

ChildClass classInstance = new ChildClass();
classInstance.PublicHelloWorld();	// works - calls PublicHelloWorld() that calls HelloWorld()
classInstance.HelloWorld();			// compilation error - HelloWorld() is protected and cannot be accessed

ParentClass classInstance = new ParentClass();
classInstance.HelloWorld();			// compilation error - HelloWorld() is protected and cannot be accessed
</enforce>
|-
!
=== static ===
| Modifier for class method. The method can be called without object pointer, just by ClassName.methodName(). Only static values/methods can be accessed from a static method.
<enforce>
class ExampleClass
{
	static void HelloWorld()
	{
		Print("Hello there");
	}
}

ExampleClass.HelloWorld();	// works

ExampleClass classInstance = new ExampleClass();
classInstance.HelloWorld();	// works
</enforce>
|-
!
=== event ===
| Hint for tools that the method should be exposed as Entity script event.
|-
!
=== override ===
| Modifier for class method indicating overriding of base class method. Compiler checks if is method present in base class and if method signature matches.
<enforce>
class ParentClass
{
	void HelloWorld()
	{
		Print("Hello world");
	}
}

class ChildClass : ParentClass
{
	override void HelloWorld()
	{
		Print("Hello there");
	}
}

ParentClass parentClassInstance = new ParentClass();
parentClassInstance.HelloWorld();	// prints "Hello world"

ChildClass childClassInstance = new ChildClass();
childClassInstance.HelloWorld();	// prints "Hello there"
</enforce>


{{Feature|warning|
Please note that an overridden <enforce inline>static</enforce> method uses the object's currently-known class:
<enforce>
class ParentClass
{
	static int GetAge()
	{
		return 50;
	}
}

class ChildClass : ParentClass
{
	override static int GetAge()
	{
		return 10;
	}
}

ChildClass child = new ChildClass();
ParentClass childAsParent = child;
Print(childAsParent.GetAge());	// returns 50
Print(child.GetAge());			// returns 10
</enforce>
}}
|-
!
=== sealed ===
| Modifier for class method. The method cannot be overridden in derived classes.
<enforce>
class ParentClass
{
	sealed void HelloWorld()
	{
		Print("Hello there");
	}
}

class ChildClass : ParentClass
{
	override void HelloWorld() // compilation error - cannot override a sealed method
	{
		Print("Hello world");
	}
}
</enforce>
|}


== Value Keywords ==

{| class="wikitable valign-top"
! Keyword
! Description
|-
!
=== owned ===
| Modifier for returning internal methods. Tells the script VM that the returning variable (string or array) must not be released.
|-
!
=== out ===
| Modifier for method parameters. It means that the argument may be changed by the method call.
<enforce>
void Method(out array<string> parameter)
{
	parameter = {};
	parameter.Insert("Hello");
	parameter.Insert("there");
}

// ...

array<string> myArray = null;
Method(myArray); // myArray is now { "Hello", "there" }
</enforce>
|-
!
=== inout ===
| Modifier for method parameters. It means that the argument will be used and may be changed by the method call.
<enforce>
class ExampleClass
{
	private ref array<string> m_aOldParameter;

	void Method(inout array<string> parameter)
	{
		m_aOldParameter = parameter;

		parameter = {};
		parameter.Insert("Hello");
		parameter.Insert("there");
	}
}

ExampleClass classInstance = new ExampleClass();

array<string> myArray = null;
classInstance.Method(myArray); // myArray is now { "Hello", "there" } and classInstance.m_aOldParameter is referencing myArray's old value
</enforce>
|-
!
=== const ===
| Declares a constant, that is a value that cannot be modified later.
<enforce>
const string MY_TEXT = "Hello there";

void Method1()
{
	Print(MY_TEXT); // will print "Hello there"
	MY_TEXT = "General Kenobi"; // compilation error - a constant is set in stone and cannot be modified
}

void Method2()
{
	const string myUnmodifiableString = "Hello there"; // constant valid for method's scope
	Print(myUnmodifiableString);
	myUnmodifiableString = "General Kenobi"; // compilation error
}
</enforce>
|-
!
=== reference ===
| Hint for tools (Material editor) that the value may be used as parameter in material.
|-
!
=== notnull ===
| Modifier for method parameter of class pointer type. It means that the method expect the parameter to never be '''null'''; if a null value is provided, a VM Exception is raised and the method is not called.
<enforce>
void Method(notnull IEntity entity) // no need to check for "if (!entity)" inside the method
{
	entity.DoSomething(); // the argument can be accessed safely
}

if (myEntity) // it is still needed to check for null before calling the method
{
	Method(myEntity);
}
</enforce>
|-
!
=== private ===
| Value can only be accessed from the class/instance methods. Mutually exclusive with "protected".
<enforce>
class ExampleClass
{
	private bool m_bIsActive;

	void SetActive(bool value)
	{
		m_bIsActive = value;
	}
}

ExampleClass classInstance = new ExampleClass();
Print(classInstance.m_bIsActive); // compilation error - m_bIsActive is private and cannot be accessed
</enforce>
|-
!
=== protected ===
| Value can only be accessed from the class/instance methods or its children. Mutually exclusive with "private".
<enforce>
class ParentClass
{
	protected bool m_bProtected;
	private bool m_bPrivate;

	void SetPrivate(bool value)
	{
		m_bPrivate = value;
	}
}

class ChildClass : ParentClass
{
	void SetProtected(bool value)
	{
		m_bProtected = value; // works - m_bProtected declaration reaches ChildClass
	}
}

ChildClass childClassInstance = new ChildClass();
Print(childClassInstance.m_bProtected); // compilation error - m_bProtected is protected and cannot be accessed
</enforce>
|-
!
=== static ===
| Value belongs to the class and not an instance of it. If public, it can be accessed without object pointer, just by <enforce>ClassName.variable</enforce>
<enforce>
class ExampleClass
{
	static bool bStaticValue;
	private static bool m_bPrivate; // it is good practice to make it protected/private and have getters/setters instead
}

Print(ExampleClass.bStaticValue);	// works
ExampleClass.bStaticValue = true;	// works

ExampleClass classInstance = new ExampleClass();
Print(classInstance.bStaticValue);	// works
classInstance.bStaticValue = true;	// works
</enforce>
{{Feature|warning|Due to the nature of per-scenario mod loading/unloading, {{hl|static}} properties '''are reset game-wide''' on modded scenario start/leave due to game and scripts' entire reload.}}
|-
!
=== autoptr ===
| Modifier for class/pointer values. Pointed object will be automatically destroyed upon end of variable lifetime (end of scope, or deletion of class, that contain it).
{{Feature|informative|This keyword is useless in scripting as all classes inherit {{hl|Managed}}, therefore are managed by [[Arma Reforger:Scripting: Automatic Reference Counting|ARC]].}}
|-
!
=== ref ===
| Strong reference. See [[Arma Reforger:Scripting: Automatic Reference Counting|Automatic Reference Counting]] for more information.
|}


== Code Keywords ==

{| class="wikitable valign-top"
! Keyword
! Description
|-
!
=== auto ===
| Guess the type of the variable. Its usage is '''not''' recommended (see {{Link|Arma Reforger:Scripting: Best Practices|Best Practices}})!
<enforce>
auto myVar = 5; // understood as int myVar = 5

// but it may have been meant as:
float myVar = 5;
</enforce>
|-
!
=== new ===
| Creates an instance of the provided class.
<enforce>
class ExampleClass
{
}

ExampleClass classInstance = new ExampleClass();
</enforce>
<enforce>
class ExampleClass
{
	void ExampleClass(int myValue) // a method named from the class is the constructor
	{
		Print(myValue);
	}
}

ExampleClass classInstance = new ExampleClass(5); // needs Constructor-defined arguments
</enforce>
|-
!
=== delete ===
| Deletes an object and sets all its references to {{hl|null}}.
{{Feature|important|It is not possible to delete an object if there is an external reference to it, like an array.}}
<enforce>
class ExampleClass
{
	void Method()
	{
		ReferencedClass obj;
		if (!obj)
			Print("obj is null");

		obj = new ReferencedClass();
		if (obj)
			Print("obj is not null");

		delete obj;
		if (!obj)
			Print("obj is null");

		// everything was fine

		obj = new ReferencedClass();
		if (obj)
			Print("obj is not null");

		array<ref ReferencedClass> list = {};
		list.Insert(obj);

		delete obj; // throws a VM Exception
	}
}
</enforce>
|-
!
=== thread ===
| Creates a script thread from a method.
{{Feature|important|
* {{hl|thread}} is to be used in {{GameCategory|armaR|Modding|Official Tools|text= Workbench}} plugins. In game, use the <enforce inline>GetGame().GetCallQueue().CallLater()</enforce> method.
*  A script thread is not a real thread and member variables are therefore "thread-safe".
}}
<enforce>
class ExampleClass
{
	// calling this method will print
	// "MainMethod start"
	// "ThreadMethod start",
	// "MainMethod end"
	// then 500ms later, "ThreadMethod end"
	void MainMethod()
	{
		Print("MainMethod start");
		thread ThreadMethod();
		Print("MainMethod end");
	}

	protected void ThreadMethod()
	{
		Print("ThreadMethod start");
		Sleep(500);
		Print("ThreadMethod end");
	}
}
</enforce>
; Thread methods are only possible within a threaded method<nowiki>:</nowiki>
* {{hl|Sleep}} takes an integer and waits for the provided amount of milliseconds
* {{hl|Wait}} takes a bool condition and holds until the provided condition is true
|-
!
=== null ===
| A null value.
|-
!
=== this ===
| Refers to the method's object itself.
<enforce>
class ExampleClass
{
	void MethodA()
	{
		this.MethodB();
	}

	void MethodB()
	{
		Print("It works");
	}
}
</enforce>

Since {{GVI|armaR|1.1.0}}, {{hl|this}} is supported in static methods and behaves like the current type.
<enforce>
class Gen1
{
	static void DoSmth() { Print("A"); }
}

class Gen2 : Gen1
{
	static override void DoSmth(Widget utility)
	{
		Print("B");
		Print(this); // > Gen2
	}
}
</enforce>
|-
!
=== super ===
| Refers to the '''parent''' class for the requested variable/method.
<enforce>
class Gen1
{
	void Method()
	{
		Print("Gen1 method");
	}
}

class Gen2 : Gen1
{
	override void Method()
	{
		Print("Gen2 method");
	}
}

class Gen3 : Gen2
{
	override void Method()
	{
		super.Method(); // prints "Gen2 method"
	}
}
</enforce>

Since {{GVI|armaR|1.1.0}}, {{hl|super}} is supported in static methods and behaves like a type.
<enforce>
class Gen1
{
	static int a = 33;
	int b = 42;
	static void ShowMessage() { Print("A"); }
}

class Gen2 : Gen1
{
	static override void ShowMessage(Widget utility)
	{
		Print("B");
		Print(super);			// > Gen1
		Print(super.a);			// > a = 33
		// Print(super.b); <- error - not a static property
		super.ShowMessage();	// > "A"
	}
}
</enforce>

|-
!
{{ArgTitle|3|vanilla|{{GVI|armaR|1.1.0}}}}
| Refers to the '''unmodded''' version of the modded variable/method.
<enforce>
class ClassA
{
	static void Hello()
	{
		Print("vanilla");
	}
}

// mod 1 content
modded class ClassA
{
	override static void Hello()
	{
		Print("modded 1");
	}
}


// mod 2 content
modded class ClassA
{
	override static void Hello()
	{
		super.Hello();
		vanilla.Hello();
		Print("modded 2");
	}
}

void Test()
{
	ClassA o = new ClassA();
	o.Hello(); // prints modded 1, vanilla, modded 2
}
</enforce>
|-
|
=== debug ===
| Triggers a breakpoint in {{Link|Arma Reforger:Script Editor}}.
{{Feature|informative|This keyword is currently not highlighted as such in Script Editor.}}
<enforce>
class MyClass
{
	[Attribute(defvalue: "0", desc: "Use breakpoints in Workbench")]
	protected bool m_bUseBreakpoints;

	static void Hello()
	{
		Print("This is debugging");
#ifdef WORKBENCH
		if (m_bUseBreakpoints)
			debug;
#endif // WORKBENCH
	}
}
</enforce>
|}


== Code Flow Keywords ==

{| class="wikitable valign-top"
! Keyword
! Description
|-
!
=== if ===
| verifies a boolean condition. If the condition is true then the code is executed.
<enforce>
void Method(int value = 0)
{
	if (value > 50)
		Print("value is > 50");
}
</enforce>
|-
!
=== else ===
| optional, declares code to be executed if the if condition is not met
<enforce>
void Method(int value = 0)
{
	if (value > 50)
		Print("value is > 50");
	else
		Print("value is <= 50");
}
</enforce>
|-
!
=== for ===
| processes code while the provided condition is met. The syntax is:
<enforce>
for (initialisation; loopCondition; completionCode)
{
	// code here
}
</enforce>
<enforce>
void MethodA(notnull array<string> words)
{
	// for (int i = 0; i < words.Count(); i++) // this if for example's sake; use '''foreach''' instead
	for (int i, count = words.Count(); i < count; ++i) // optimised
	{
		Print(words[i]);
	}
}

void MethodB(notnull array<string> words)
{
	int i; // auto-initialised to zero
	int count = words.Count();
	for (; i < count; i++) // initialisation is optional
	{
		Print(words[i]);
	}
}

void MethodC(notnull array<string> words)
{
	for (int i, count = words.Count(); i < count;) // so is completionCode
	{
		Print(words[i]);
		i++; // do not forget it!
	}
}
</enforce>
|-
!
=== foreach ===
| processes code for each element of an iterable object (e.g an array). Iteration separator is{{hl|:}}.
<enforce>
// array example
void Method(notnull array<string> words)
{
	foreach (string word : words)
	{
		Print(word);
	}

	foreach (int index, string word : words)
	{
		PrintFormat("word #%1 is %2", index, word);
	}
}
</enforce>
<enforce>
// map example
void Method(notnull map<string, int> data)
{
	foreach (string key, int value : data)
	{
		PrintFormat("Key %1's value is %2", key, value);
	}
}
</enforce>
|-
!
=== while ===
| processes code while condition is met. Beware, as it can lock the program on wrong conditions!
<enforce>
void Method(array<string> words)
{
	int i = 0;
	while (i < words.Count())
	{
		Print(words[i]);
		i++; // do not forget it!
	}
}
</enforce>
|-
!
=== switch ===
| switches the code to execute depending on the condition
<enforce>
void Method(string word)
{
	switch (word)
	{
		case "Hello":
			Print("it's Hello");
			break;

		case "there":
			Print("it's there");
			break;

		default:
			Print("it's not interesting.");
			break;
	}
}
</enforce>
|-
|
=== continue ===
| Used to skip to the next iteration in {{hl|for}}, {{hl|foreach}}, {{hl|while}} loops
<enforce>
class ExampleClass
{
	// this method will print 0, 1, 2, 4
	void Skip3()
	{
		for (int i; i < 5; i++)
		{
			if (i == 3)
				continue;

			Print(i.ToString());
		}
	}

	void MethodB()
	{
		foreach (IEntity entity : m_aEntities)
		{
			if (!entity)
				continue;

			Print(entity);
		}
	}
}
</enforce>
|-
!
=== return ===
| Exits the method immediately with the provided value if any.
<enforce>
class ExampleClass
{
	void PrintHelloThere(bool print)
	{
		if (!print)
			return; // ends here if print is false

		Print("Hello there");
	}

	float GetDistanceNotZero(vector v1, vector v2)
	{
		if (v1 == v2)
			return -1;

		return vector.Distance(v1, v2);
	}
}
</enforce>
|}


{{GameCategory|armaR|Modding|Scripting|Guidelines}}

{{TOC|side}}
Performance is an important aspect of scripting, as poor performance can tank the whole gaming experience, if not the game itself.

* What is tanking performances
** Crazy requests
** Memory saturation
** Redundant code operations
* How to benchmark/identify what slows down things
** What is acceptable?
** What is not?


== Performance Enemies ==

Many if not all of the usual performance issues can see some of these questions asked:
* is it ''needed?
* is it ''needed there?''
* is it ''needed that much?''
* is it ''needed immediately?''
* is it ''needed that frequently?''

and the respective solutions to positive replies to these questions would be:
* don't do it: quite straightforward, can mean to remove the code or to replace it with a simpler code
* don't do it ''there'': the concerned class might be dealing with responsibilities that are out of its scope
* don't do it ''that much'': the structure can be rethought in order to have fewer operations to be executed
* don't do it ''in one frame'': the calculation can be spread over multiple frames and result delayed and cached
* don't do it ''that frequently'': the code can be set to run every X seconds, result being delayed and cached until the next iteration

=== Not Needed ===

==== Problem ====
Partially unneeded calculation is done.

==== Solution ====
* Remove the unneeded code
* Split the code to only do needed processing in each case

=== Misplaced ===

==== Problem ====
A calculation/storage is done on every instance whereas calculation could be centralised.

==== Solution ====
Move the responsibility and the data to a dedicated class ('''S''' from {{Link|https://en.wikipedia.org/wiki/SOLID}}, '''S'''ingle '''R'''esponsibility '''P'''rinciple).

==== Example ====
{| class="wikitable" style="width: 100%"
! style="width: 50%" | Original
! Optimised
|- style="vertical-align: top"
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref PotentialTarget> m_aBigObjectList = { /* ... */ };

	protected array<ref PotentialTarget> GetTargets()
	{
		array<ref PotentialTarget> result = {};
		foreach (PotentialTarget object : m_aBigObjectList)
		{
			if (object.IsEnemyTo(this.GetFaction()))
				result.Insert(object);
		}

		return result;
	}
}
</enforce>
| <enforce>
class EnemyManager
{
	protected ref map<Faction, ref array<ref PotentialTarget>> m_mTargetMap;

	void EnemyManager(array<ref PotentialTarget> potentialTargets)
	{
		m_mTargetMap = new map<Faction, ref array<ref PotentialTarget>>();

		array<ref PotentialTarget> factionTargets;
		foreach (Faction faction : Faction.GetAllFactions())
		{
			factionTargets = {};
			foreach (PotentialTarget potentialTarget : potentialTargets)
			{
				if (potentialTarget.IsEnemyTo(faction))
					factionTargets.Insert(potentialTarget);
			}

			m_mTargetMap.Set(faction, factionTargets);
		}
	}

	array<ref PotentialTarget> GetTargets(Faction faction)
	{
		return m_mTargetMap.Get(faction);
	}
}

class PerformanceExample : IEntity
{
	protected ref EnemyManager m_EnemyManager;

	void PerformanceExample(notnull EnemyManager enemyManager)
	{
		m_EnemyManager = enemyManager;
	}

	protected array<ref PotentialTarget> GetTargets()
	{
		return m_EnemyManager.GetTargets(this.GetFaction());
	}
}
</enforce>
|}


=== Ill-Conceived ===

==== Problem ====
A big array of data is processed at once. Going through all the data is not needed.

==== Solution ====
Stop as soon as an acceptable result has been obtained.

==== Example ====
{| class="wikitable" style="width: 100%"
! style="width: 50%" | Original
! Optimised
|- style="vertical-align: top"
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref AliveOrNotObject> m_aBigObjectList = { /* ... */ };

	protected int GetNumberOfAliveObjects()
	{
		int result;
		foreach (AliveOrNotObject object : m_aBigObjectList)
		{
			if (object.IsAlive())
				result++;
		}

		return result;
	}

	bool IsAnObjectAlive()
	{
		// heavy: goes through all objects to know if -one- is alive
		return GetNumberOfAliveObjects() > 0;
	}
}
</enforce>
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref AliveOrNotObject> m_aBigObjectList = { /* ... */ };

	bool IsAnObjectAlive()
	{
		foreach (AliveOrNotObject object : m_aBigObjectList)
		{
			if (object.IsAlive())
				return true; // stops on the first occurence
		}

		return false; // goes through all instances to reach false - less likely
	}
}
</enforce>
|}

=== Spread ===

==== Problem ====
A big array of data is processed at once. The calculation itself is not the issue, the amount of items is.<br>
'''or'''<br>
A heavy calculation is done, and only one such operation should happen per frame.

==== Solution ====
Spread the calculation over multiple frames.

==== Example 1 ====
Array size issue:
{| class="wikitable" style="width: 100%"
! style="width: 50%" | Original
! Optimised
|- style="vertical-align: top"
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref AliveOrNotObject> m_aBigObjectList = { /* ... */ };

	void EOnInit(IEntity owner)
	{
		GetGame().GetCallqueue().CallLater(PrintResult, 250, true);
	}

	int GetNumberOfAliveObjects()
	{
		int result = 0;
		foreach (AliveOrNotObject object : m_aBigObjectList)
		{
			if (object.IsAlive())
				result++;
		}

		return result;
	}

	void PrintResult()
	{
		Print("Alive objects = " + GetNumberOfAliveObjects());
	}
}
</enforce>
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref AliveOrNotObject> m_aBigObjectList = { /* ... */ };
	protected ref array<ref AliveOrNotObject> m_aObjectsToBeProcessed = {};
	protected bool m_bIsCalculating;
	protected int m_iTempResult;
	protected int m_iAliveCountBuffer;

	void EOnInit(IEntity owner)
	{
		Calculate();
		GetGame().GetCallqueue().CallLater(PrintResult, 250, true);
	}

	void EOnFrame(IEntity owner, float timeSlice)
	{
		if (m_bIsCalculating)
			Calculate();

		// other frame things
		// ...
	}

	void Calculate()
	{
		int objCount = m_aObjectsToBeProcessed.Count();
		if (objCount < 1)
		{
			m_bIsCalculating = true;
			m_iTempResult = 0;
			m_aObjectsToBeProcessed.Copy(m_aBigObjectList);
		}

		// max 10k items slice
		for (int i, maxCount = Math.Min(objCount, 10000); i < maxCount; i++)
		{
			AliveOrNotObject object = m_aObjectsToBeProcessed[0];	// always @ index 0
																	// for we remove the first item later
			if (object.IsAlive())
				m_iTempResult++;

			m_aObjectsToBeProcessed.Remove(0);
			objCount--;
		}

		if (objCount < 1)
		{
			m_iAliveCountBuffer = m_iTempResult;
			GetGame().GetCallqueue().CallLater(Calculate, 1000); // restart calculation in 1 second
			m_bIsCalculating = false;
		}
	}

	int GetNumberOfAliveObjects()
	{
		return m_iAliveCountBuffer;
	}

	void PrintResult()
	{
		Print("Alive objects = " + GetNumberOfAliveObjects());
	}
}
</enforce>
|}

==== Example 2 ====
Heavy calculation issue:
{| class="wikitable" style="width: 100%"
! style="width: 50%" | Original
! Optimised
|- style="vertical-align: top"
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref Player> m_aPlayers = { /* ... */ };
	protected ref map<ref Player, bool> m_mCastResult;
	protected BaseWorld m_World;

	void PerformanceExample()
	{
		m_mCastResult = new map<ref Player, bool>();
		m_World = GetGame().GetWorld();
	}

	void CheckLineOfSight()
	{
		float result;
		TraceParam traceParam;
		foreach (Player player : m_aPlayers)
		{
			traceParam = new TraceParam();
			traceParam.Start = this.Position();
			traceParam.End = player.Position();

			// a Trace is a very expensive operation
			result = m_World.TraceMove(traceParam, null);
			m_mCastResult.Set(player, result == 1);
		}
	}
}
</enforce>
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref Player> m_aPlayers = { /* ... */ };
	protected ref map<ref Player, bool> m_mCastResult;
	protected BaseWorld m_World;
	protected int m_iIndex = -1;
	protected bool m_bIsCalculating;

	void PerformanceExample()
	{
		m_mCastResult = new map<ref Player, bool>();
		m_World = GetGame().GetWorld();
	}

	void EOnFrame(IEntity owner, float timeSlice)
	{
		if (m_bIsCalculating)
			CheckLineOfSight();
	}

	void CheckLineOfSight()
	{
		m_iIndex++;
		m_bIsCalculating = m_iIndex < m_aPlayers.Count();
		if (!m_bIsCalculating)
		{
			m_iIndex = -1;
			return;
		}

		Player player = m_aPlayers[m_iIndex];
		TraceParam traceParam = new TraceParam();
		traceParam.Start = this.Position();
		traceParam.End = player.Position();

		// only one Trace per frame
		float result = m_World.TraceMove(traceParam, null);
		m_mCastResult.Set(player, result == 1);
	}
}
</enforce>
|}

=== Immediate Calculation ===

==== Problem ====
A heavy operation is done frequently.

==== Solution ====
Do the heavy operation once, store its result in a member variable and accessible through a getter.

==== Example ====
{| class="wikitable" style="width: 100%"
! style="width: 50%" | Original
! Optimised
|- style="vertical-align: top"
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref AliveOrNotObject> m_aBigObjectList = { /* ... */ };

	void EOnInit(IEntity owner)
	{
		GetGame().GetCallqueue().CallLater(PrintResult, 250, true);
	}

	int GetNumberOfAliveObjects()
	{
		int result = 0;
		foreach (AliveOrNotObject object : m_aBigObjectList)
		{
			if (object.IsAlive())
				result++;
		}

		return result;
	}

	void PrintResult()
	{
		Print("Alive objects = " + GetNumberOfAliveObjects());
	}
}
</enforce>
| <enforce>
class PerformanceExample : IEntity
{
	protected ref array<ref AliveOrNotObject> m_aBigObjectList = { /* ... */ };
	protected int m_iAliveCountBuffer;

	void EOnInit(IEntity owner)
	{
		GetGame().GetCallqueue().CallLater(Calculate, 1000, true);	// calculate only every second
		GetGame().GetCallqueue().CallLater(PrintResult, 250, true);	// display result every 1/4 second
	}

	void Calculate()
	{
		int result = 0;
		foreach (AliveOrNotObject object : m_aBigObjectList)
		{
			if (object.IsAlive())
				result++;
		}

		m_iAliveCountBuffer = result;
	}

	int GetNumberOfAliveObjects()
	{
		return m_iAliveCountBuffer;
	}

	void PrintResult()
	{
		Print("Alive objects = " + GetNumberOfAliveObjects());
	}
}
</enforce>
|}


== Specific Issues ==

=== Big Foreach ===

==== Problem ====
Going through one big list of items in one operation.

==== Specific Solution ====
* Use a smaller list by being more precise
* Continue out of the scope if the item is not viable for the operation

=== High-Frequency Scripts ===

==== Problem ====
OnEachFrame calculations - are they needed?

==== Specific Solution ====
* Less resource-hungry calls
* Buffering/caching

=== High-Performance Request ===

==== Problem ====
Is a 10km raycast really needed?

==== Solution ====
* Reconsider the need
* Find a smarter solution


== Benchmark ==

=== What Should Be Of Concern ===

* Non time-critical operations that are made in the same frame
* High RAM usage

=== What Should Not Be Of Concern ===

* Normal operations that are required and that one cannot do without (yes, check if the player is alive before performing action, otherwise the feature breaks)
* One-time required big operation (spawning a base = data loading, no can do anything about it)
